from PIL import Image, ImageDraw
im = Image.open('radiograph.jpg')
def gridcrop(box, name, s=2.0):
    c=im.crop(box).resize((int((box[2]-box[0])*s),int((box[3]-box[1])*s)),Image.LANCZOS).convert('RGB')
    d=ImageDraw.Draw(c)
    for x in range(box[0],box[2],50):
        cx=int((x-box[0])*s); d.line([(cx,0),(cx,c.height)],fill=(255,120,120)); d.text((cx+2,2),str(x),fill=(255,0,0))
    for y in range(box[1],box[3],50):
        cy=int((y-box[1])*s); d.line([(0,cy),(c.width,cy)],fill=(255,120,120)); d.text((2,cy+2),str(y),fill=(255,0,0))
    c.save(f'/tmp/{name}.png'); print(name,c.size)
gridcrop((550,420,1000,1000),'z_loR_context',2.0)
EOF", "description": "Context view lower right quadrant"}
